-- 109: Original BrillaPrep 4CH1 beta questions, part 1.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_001', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which change is physical rather than chemical?', 'multiple_choice', '["A. Melting pure ice","B. Burning magnesium","C. Rusting iron","D. Neutralising acid"]', 'A', 'Melting changes state without forming a new substance, and the water molecules remain unchanged. Therefore the correct answer is A: Melting pure ice.', 'easy', 1, 1, 90, 'st_edx_4ch1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_002', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'An atom has 17 protons and 18 electrons. What is its charge?', 'multiple_choice', '["A. +1","B. −1","C. 0","D. −17"]', 'B', 'One more electron than proton gives one additional negative elementary charge overall. Therefore the correct answer is B: −1.', 'medium', 2, 2, 90, 'st_edx_4ch1_1', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_003', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why does molten sodium chloride conduct electricity?', 'multiple_choice', '["A. It contains free neutrons","B. Its ions lose charge","C. Its ions are free to move","D. It becomes a simple metal"]', 'C', 'Melting frees charged ions from fixed lattice positions so they can carry current. Therefore the correct answer is C: Its ions are free to move.', 'hard', 1, 1, 90, 'st_edx_4ch1_1', 'Explain', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_004', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What type of bonding holds atoms together in methane?', 'multiple_choice', '["A. Ionic bonding","B. Metallic bonding","C. Hydrogen ions","D. Covalent bonding"]', 'D', 'Carbon and hydrogen atoms share electron pairs, which is covalent bonding. Therefore the correct answer is D: Covalent bonding.', 'easy', 2, 2, 90, 'st_edx_4ch1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_005', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Calculate the relative formula mass of CO₂ using C = 12 and O = 16.', 'multiple_choice', '["A. 44","B. 28","C. 32","D. 56"]', 'A', 'One carbon contributes 12 and two oxygens contribute 32, giving 44 in total. Therefore the correct answer is A: 44.', 'medium', 3, 3, 90, 'st_edx_4ch1_1', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_006', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'How many moles are in 9.0 g of water, Mr = 18?', 'multiple_choice', '["A. 2.0 mol","B. 0.50 mol","C. 9.0 mol","D. 162 mol"]', 'B', 'Amount in moles equals mass divided by molar mass: 9.0 ÷ 18 = 0.50 mol. Therefore the correct answer is B: 0.50 mol.', 'hard', 2, 2, 90, 'st_edx_4ch1_1', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_007', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What is the empirical formula for equal moles of magnesium and oxygen atoms?', 'multiple_choice', '["A. Mg₂O","B. MgO₂","C. MgO","D. Mg₂O₃"]', 'C', 'An equal 1:1 mole ratio gives one magnesium atom for each oxygen atom in the formula. Therefore the correct answer is C: MgO.', 'easy', 1, 1, 90, 'st_edx_4ch1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_008', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'At the cathode during electrolysis, what happens to positive ions?', 'multiple_choice', '["A. They lose electrons","B. They gain protons","C. They become negative ions","D. They gain electrons"]', 'D', 'Cations are attracted to the negative cathode and are reduced by accepting electrons. Therefore the correct answer is D: They gain electrons.', 'medium', 2, 2, 90, 'st_edx_4ch1_1', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_009', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What pH is expected for a neutral aqueous solution at room temperature?', 'multiple_choice', '["A. 7","B. 0","C. 5","D. 14"]', 'A', 'A neutral solution has equal hydrogen and hydroxide ion concentrations and pH 7 at room temperature. Therefore the correct answer is A: 7.', 'hard', 1, 1, 90, 'st_edx_4ch1_1', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_010', 'topic_edx_4ch1_1', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which apparatus most accurately delivers 25.0 cm³ in a titration?', 'multiple_choice', '["A. Beaker","B. Volumetric pipette","C. Measuring cylinder","D. Evaporating basin"]', 'B', 'A volumetric pipette is calibrated to transfer one precise fixed volume. Therefore the correct answer is B: Volumetric pipette.', 'easy', 3, 3, 90, 'st_edx_4ch1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_011', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why do Group 1 metals become more reactive down the group?', 'multiple_choice', '["A. Their nuclei have fewer protons","B. They gain electrons more easily","C. The outer electron is lost more easily","D. Their atoms become smaller"]', 'C', 'Increased shielding and distance weaken attraction between the nucleus and the outer electron. Therefore the correct answer is C: The outer electron is lost more easily.', 'medium', 1, 1, 90, 'st_edx_4ch1_2', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_012', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What gas forms when a reactive metal reacts with dilute hydrochloric acid?', 'multiple_choice', '["A. Oxygen","B. Chlorine","C. Carbon dioxide","D. Hydrogen"]', 'D', 'Metal plus hydrochloric acid produces a chloride salt and hydrogen gas. Therefore the correct answer is D: Hydrogen.', 'hard', 2, 2, 90, 'st_edx_4ch1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_013', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which gas turns damp red litmus paper blue?', 'multiple_choice', '["A. Ammonia","B. Chlorine","C. Carbon dioxide","D. Hydrogen"]', 'A', 'Ammonia dissolves in water to form an alkaline solution that turns red litmus blue. Therefore the correct answer is A: Ammonia.', 'easy', 1, 1, 90, 'st_edx_4ch1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_014', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What flame colour indicates sodium ions?', 'multiple_choice', '["A. Lilac","B. Yellow","C. Brick red","D. Blue-green"]', 'B', 'Excited sodium ions emit a characteristic intense yellow light in a flame test. Therefore the correct answer is B: Yellow.', 'medium', 2, 2, 90, 'st_edx_4ch1_2', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_015', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which metal can be extracted from its oxide using carbon?', 'multiple_choice', '["A. Potassium","B. Aluminium","C. Iron","D. Magnesium"]', 'C', 'Iron is below carbon in the reactivity series, so carbon can reduce iron oxide. Therefore the correct answer is C: Iron.', 'hard', 3, 3, 90, 'st_edx_4ch1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_016', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What observation identifies chloride ions after acidifying with nitric acid?', 'multiple_choice', '["A. A blue precipitate with sodium hydroxide","B. A lilac flame","C. A squeaky pop","D. A white precipitate with silver nitrate"]', 'D', 'Silver ions react with chloride ions to form insoluble white silver chloride. Therefore the correct answer is D: A white precipitate with silver nitrate.', 'easy', 2, 2, 90, 'st_edx_4ch1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_017', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why is aluminium resistant to further corrosion?', 'multiple_choice', '["A. A protective oxide layer forms","B. It contains no electrons","C. It is completely unreactive","D. It dissolves in water instantly"]', 'A', 'A thin, adherent aluminium oxide film blocks oxygen and water from the metal beneath. Therefore the correct answer is A: A protective oxide layer forms.', 'medium', 1, 1, 90, 'st_edx_4ch1_2', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_018', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which gas relights a glowing splint?', 'multiple_choice', '["A. Hydrogen","B. Oxygen","C. Carbon dioxide","D. Ammonia"]', 'B', 'Oxygen supports combustion strongly enough to relight a glowing wooden splint. Therefore the correct answer is B: Oxygen.', 'hard', 2, 2, 90, 'st_edx_4ch1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_019', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What is oxidation in terms of electrons?', 'multiple_choice', '["A. Gain of electrons","B. Sharing neutrons","C. Loss of electrons","D. Loss of protons"]', 'C', 'Oxidation is electron loss, while reduction is electron gain in redox reactions. Therefore the correct answer is C: Loss of electrons.', 'easy', 1, 1, 90, 'st_edx_4ch1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_020', 'topic_edx_4ch1_2', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why is cryolite used when extracting aluminium?', 'multiple_choice', '["A. It supplies carbon dioxide","B. It makes aluminium less conductive","C. It removes every impurity","D. It lowers the operating temperature of electrolysis"]', 'D', 'Dissolving alumina in molten cryolite lowers the melting point and reduces energy demand. Therefore the correct answer is D: It lowers the operating temperature of electrolysis.', 'medium', 3, 3, 90, 'st_edx_4ch1_2', 'Explain', 'AO2', 'board_edexcel');
